      "path": "mcp/src/utils/confirmation-guard.ts",
      "content": "import type { RequestId } from \"@modelcontextprotocol/sdk/types.js\";\nimport { readDisplayedEnvId } from \"./env-binding.js\";\nimport { t } from \"../i18n/index.js\";\nimport { isFormElicitationSupported, requestChoiceElicitation } from \"./elicitation.js\";\nimport { destructiveConfirmationKeys, resolveDestructiveAction } from \"./destructive-actions.js\";\nimport { debug } from \"./logger.js\";\nimport { isSkippedByList, parseSkipList } from \"./skip-list.js\";\n\n/**\n * 破坏性动作的**执行前确认**（护栏，不是安全边界）。\n *\n * 定位：让一次不可逆的删除，在执行前变成一次看得见的选择。三条设计取舍：\n *\n *   1. **客户端没声明 form 能力 ⇒ 不弹、照常执行**（不阻塞、不降级成聊天里的二次询问）。\n *   2. **客户端自行应答（< 500ms）不算「人的决定」**：用户把客户端设成完全访问/不询问，本身就是在说\n *      \"别问我\"，拦住他等于替他做决定。这类应答按\"未询问\"放行，可用\n *      `CLOUDBASE_MCP_ELICIT_AUTO_APPROVE=block` 反过来拦下。判据是耗时，不是 `action` 的值。\n *   3. **被拦下时返回正常结果**（`isError` 不置位、`structuredContent` 里不放 `success`）：\n *      标成失败会让客户端渲染成出错、模型可能自动重试同一个删除。注意包装层会把\n *      `structuredContent.success === false` 自动标成 MCP 错误（见 tool-result.ts），所以这里不能带 `success`。\n *\n * 首次接线点：`tool-wrapper.ts` 的 `createWrappedHandler`（全部工具的唯一必经之路）。\n */\n\n/** 确认窗口：必须窄于客户端的请求超时（60s），否则窗口会先被客户端关掉 */\nexport const CONFIRMATION_TIMEOUT_MS = 45_000;\n\n/** 客户端自行应答的临界值。实测：客户端自行应答 0~2ms，人读完文案点按钮约 1s 以上 */\nexport const AUTO_ANSWER_THRESHOLD_MS = 500;\n\n/** 逗号分隔的跳过清单：可写 `工具名` 或 `工具名.action`，区分大小写，无通配 */\nexport const SKIP_ENV_NAME = \"CLOUDBASE_MCP_SKIP_ELICITATIONS\";\n\n/** 客户端自行应答时是否放行：`allow`（默认）/ `block` */\nexport const AUTO_APPROVE_ENV_NAME = \"CLOUDBASE_MCP_ELICIT_AUTO_APPROVE\";\n\nexport type ConfirmationStatus =\n    | \"not_applicable\"\n    | \"accepted\"\n    | \"auto_approved\"\n    | \"auto_approved_blocked\"\n    | \"skipped\"\n    | \"unsupported\"\n    | \"cancelled\"\n    | \"timeout\"\n    | \"error\";\n\n/** 包装层只需要知道两件事：要不要拦、以及拦下时返回什么 */\nexport type GuardDecision =\n    | { intercept: false; status: ConfirmationStatus }\n    | {\n          intercept: true;\n          status: ConfirmationStatus;\n          result: {\n              content: Array<{ type: \"text\"; text: string }>;\n              structuredContent: Record<string, unknown>;\n          };\n      };\n\nexport type ConfirmationServer = {\n    server?: {\n        getClientCapabilities?: () => unknown;\n        elicitInput?: (params: any, options?: any) => Promise<any>;\n    };\n    cloudBaseOptions?: { envId?: string };\n    ide?: string;\n    client?: string;\n};\n\nlet warnedSkipEntries = false;\n\n/**\n * 跳过清单的合法取值：名单内的工具名，或 `工具名.action`。\n * 未知取值**显式告警但只告警一次** —— 静默忽略会让用户以为已经关掉了。\n * （不做成启动即退出：一个拼错的变量名不该让整个 MCP 服务不可用。）\n */\nfunction knownSkipNames(): Set<string> {\n    const names = new Set<string>();\n    for (const key of destructiveConfirmationKeys()) {\n        names.add(key);\n        names.add(key.slice(0, key.indexOf(\".\")));\n    }\n    return names;\n}\n\nexport function readSkipList(): string[] {\n    const entries = parseSkipList(process.env[SKIP_ENV_NAME]);\n    const known = knownSkipNames();\n    const unknown = entries.filter((entry) => !known.has(entry));\n    if (unknown.length > 0 && !warnedSkipEntries) {\n        warnedSkipEntries = true;\n        console.error(\n            `[cloudbase-mcp] ${SKIP_ENV_NAME} 含无法识别的条目，已忽略：${unknown.join(\", \")}。` +\n                `合法取值（区分大小写、无通配）：${[...known].sort().join(\", \")}`,\n        );\n    }\n    return entries;\n}\n\n/** 本次调用是否需要跳过确认 */\nexport function isSkipped(actionKey: string): boolean {\n    const toolName = actionKey.slice(0, actionKey.indexOf(\".\"));\n    return isSkippedByList(readSkipList(), toolName, actionKey);\n}\n\n/** 客户端自行应答时是否放行；取值非法时告警并回落默认（放行） */\nexport function readAutoApprovePolicy(): \"allow\" | \"block\" {\n    const raw = (process.env[AUTO_APPROVE_ENV_NAME] || \"allow\").trim().toLowerCase();\n    if (raw === \"allow\" || raw === \"block\") {\n        return raw;\n    }\n    console.error(\n        `[cloudbase-mcp] ${AUTO_APPROVE_ENV_NAME} 只接受 allow / block，收到 \"${raw}\"，按 allow 处理。`,\n    );\n    return \"allow\";\n}\n\nfunction resolveEnvId(server: ConfirmationServer): string {\n    return readDisplayedEnvId(server.cloudBaseOptions?.envId) ?? t(\"confirmation.message.unknownEnv\");\n}\n\nfunction blockedText(\n    status: ConfirmationStatus,\n    actionKey: string,\n    targetInfo: { resource: string; envId: string },\n    params: Record<string, string | number>,\n): string {\n    const keyByStatus = {\n        cancelled: \"confirmation.blocked.cancelled\",\n        timeout: \"confirmation.blocked.timeout\",\n        error: \"confirmation.blocked.error\",\n        auto_approved_blocked: \"confirmation.blocked.autoApprovedBlocked\",\n    } as const;\n    const reasonKey = keyByStatus[status as keyof typeof keyByStatus] ?? \"confirmation.blocked.error\";\n    return [\n        t(reasonKey, params),\n        t(\"confirmation.blocked.target\", targetInfo),\n        t(\"confirmation.hint.release\", { action: actionKey }),\n        `[elicit] status=${status} executed=false`,\n    ].join(\"\\n\");\n}\n\n/**\n * 命中名单时先确认再执行。返回 `intercept: true` 表示**不要执行**，把 `result` 原样返回给客户端。\n * 任何内部异常都不能让工具调用失败：出错时按\"未执行\"处理（不同错误，也不放行）。\n */\nexport async function guardDestructiveAction(\n    server: ConfirmationServer,\n    params: { toolName: string; args: unknown; extra?: { requestId?: RequestId } },\n): Promise<GuardDecision> {\n    const resolved = resolveDestructiveAction(params.toolName, params.args);\n    if (!resolved) {\n        return { intercept: false, status: \"not_applicable\" };\n    }\n    const { key, spec } = resolved;\n\n    if (isSkipped(key)) {\n        debug(\"破坏性动作命中跳过清单，按不确认执行\", { tool: params.toolName, action: key });\n        return { intercept: false, status: \"skipped\" };\n    }\n\n    // 客户端没声明 form 能力 ⇒ 不弹、照常执行（绝不阻塞）。\n    // 能力读取本身异常时同样按\"不支持\"处理：这时候也没法弹，但绝不能因此让工具调用失败。\n    let formCapable = false;\n    try {\n        formCapable = isFormElicitationSupported(server);\n    } catch (error) {\n        debug(\"读取 elicitation 能力失败，按不支持处理\", {\n            tool: params.toolName,\n            error: error instanceof Error ? error.message : String(error),\n        });\n    }\n    if (!formCapable) {\n        return { intercept: false, status: \"unsupported\" };\n    }\n\n    const confirmLabel = t(\"confirmation.option.confirm\");\n    const cancelLabel = t(\"confirmation.option.cancel\");\n    const target = spec.target((params.args ?? {}) as Record<string, unknown>);\n    const targetInfo = {\n        resource: target.resource ?? t(\"confirmation.message.unknownResource\"),\n        envId: resolveEnvId(server),\n    };\n\n    let outcome;\n    try {\n        outcome = await requestChoiceElicitation(server, {\n            message: t(target.messageKey ?? spec.messageKey, {\n                resource: targetInfo.resource,\n                ...(typeof target.count === \"number\" ? { count: target.count } : {}),\n                envId: targetInfo.envId,\n            }),\n            field: \"confirm\",\n            // 受控选项：客户端只能回这两个值之一（不接受自由文本，见 MCP 规范 MUST NOT）\n            options: [confirmLabel, cancelLabel],\n            // 默认落在\"取消\"上：默认值就是\"不执行\"\n            defaultOption: cancelLabel,\n            timeoutMs: CONFIRMATION_TIMEOUT_MS,\n            context: {\n                toolName: params.toolName,\n                ide: server.ide,\n                client: server.client,\n                relatedRequestId: params.extra?.requestId,\n                cloudBaseOptions: server.cloudBaseOptions,\n            },\n        });\n    } catch (error) {\n        const reason = error instanceof Error ? error.message : String(error);\n        return {\n            intercept: true,\n            status: \"error\",\n            result: {\n                content: [{ type: \"text\", text: blockedText(\"error\", key, targetInfo, { reason }) }],\n                structuredContent: { status: \"error\", executed: false, tool: params.toolName },\n            },\n        };\n    }\n\n    // 表单里选了\"确认\"才算同意\n    if (outcome.status === \"accepted\" && outcome.value === confirmLabel) {\n        debug(\"破坏性动作已确认\", { tool: params.toolName, action: key, durationMs: outcome.durationMs });\n        return { intercept: false, status: \"accepted\" };\n    }\n\n    /** 拦下并给出说明；`durationMs` 只用于把\"你点的取消\"和\"自动审批被拦\"区分开 */\n    const block = (status: ConfirmationStatus, extraParams: Record<string, string | number> = {}) => ({\n        intercept: true as const,\n        status,\n        result: {\n            content: [{ type: \"text\" as const, text: blockedText(status, key, targetInfo, extraParams) }],\n            structuredContent: { status, executed: false, tool: params.toolName },\n        },\n    });\n\n    // 客户端**填了表单**却选了取消 ⇒ 按取消处理。回得再快也不改变\"它明确回了取消\"这件事。\n    if (outcome.status === \"accepted\") {\n        return block(\"cancelled\", { durationMs: outcome.durationMs, reason: \"form_returned_cancel_option\" });\n    }\n\n    // 只有\"没带内容的 decline/cancel\"才适用\"即时应答＝客户端处于不询问模式\"这条规则\n    if (outcome.status === \"declined\") {\n        const instant = outcome.durationMs < AUTO_ANSWER_THRESHOLD_MS;\n        if (instant && readAutoApprovePolicy() === \"allow\") {\n            debug(\"客户端自行应答，按未询问放行\", {\n                tool: params.toolName,\n                action: key,\n                durationMs: outcome.durationMs,\n            });\n            return { intercept: false, status: \"auto_approved\" };\n        }\n        return instant\n            ? block(\"auto_approved_blocked\", { durationMs: outcome.durationMs })\n            : block(\"cancelled\", { durationMs: outcome.durationMs, reason: outcome.reason });\n    }\n\n    if (outcome.status === \"timeout\") {\n        return block(\"timeout\", { seconds: Math.round(CONFIRMATION_TIMEOUT_MS / 1000) });\n    }\n\n    // 其余（error / 回值不在选项内 / elicitInput 不可用）一律不放行\n    return block(\"error\", { reason: outcome.reason ?? \"unknown\" });\n}\n"
    },
    {
      "path": "mcp/src/utils/destructive-actions.ts",
      "content": "import { t, type MessageKey } from \"../i18n/index.js\";\nimport { getSqlVerb, isDestructiveSql, splitSqlStatements, stripLeadingSqlComments } from \"./sql-risk.js\";\n\n/**\n * 破坏性动作的**单一真源**。\n *\n * 为什么需要它：MCP 注解（`destructiveHint`）是**工具级**的，而破坏性动作是**工具内的 action** ——\n * `manageFunctions` 里 `queryFunctions`（读）与 `deleteFunction`（删）只能共用一个注解值，\n * 模型与客户端都看不出\"这一次调用要删东西\"。所以名单必须按 `工具名.action` 单独维护。\n *\n * 两条约束：\n *   1. **只放\"执行前确认\"的触发面**，不放\"值得记一笔\"的一切写操作 —— 名单越大，误伤越多；\n *   2. 名字像破坏性、但有意不确认的，必须写进 `DESTRUCTIVE_EXEMPT_ACTIONS` **并给理由**，\n *      由 `destructive-actions.test.ts` 保证\"既不登记、也不豁免\"的动作会让测试变红。\n */\n\n/**\n * 谓词触发面：有些动作**只有参数确实危险时**才该确认（典型是 SQL —— `execute` 里既可能跑\n * `SELECT` 也可能跑 `DELETE`，只看 action 名会把两者一起拦下）。\n *\n * 约定：`when` 返回 `false` ⇒ **这次调用不命中**，按未登记处理（既不弹确认、也不走拦截返回）；\n * 省略 `when` ⇒ 与既有条目一致（命中 action 即触发）。谓词必须是纯函数、只看参数，不读文件/不联网。\n */\nexport type DestructiveActionPredicate = (args: Record<string, unknown>) => boolean;\n\n/** 需要用户核对的信息：只取标识类字段，密钥类一律不取 */\nexport type DestructiveTarget = {\n    /** 资源标识（云函数名 / 集合名 / 存储路径 / 服务名 / 实例 ID） */\n    resource?: string;\n    /** 批量操作的数量。只有入参里真有条数时才填，不要用缺省值冒充 */\n    count?: number;\n    /** 同一 action 有不止一种诚实说法时，覆盖 spec.messageKey */\n    messageKey?: MessageKey;\n};\n\nexport type DestructiveActionSpec = {\n    /** 确认文案的词典 key（文案里必须带 {resource}） */\n    messageKey: MessageKey;\n    /** 从入参抽\"这次要动什么\"；取不到时返回占位，不抛错 */\n    target: (args: Record<string, unknown>) => DestructiveTarget;\n    /** 可选的参数谓词：只有它返回 true 时这次调用才命中（见类型注释） */\n    when?: DestructiveActionPredicate;\n};\n\n// ---- PostgreSQL：按**参数里的 SQL** 判定，而不是按 action 名 ----\n\n/** 语句预览长度上限：确认框里要能看清\"是哪条语句\"，又不至于把整段脚本倒进去 */\nconst SQL_PREVIEW_MAX = 240;\n\nfunction asSqlText(value: unknown): string {\n    return typeof value === \"string\" ? value : \"\";\n}\n\nfunction sqlPreview(statement: string): string {\n    const flattened = statement.replace(/\\s+/g, \" \").trim();\n    return flattened.length > SQL_PREVIEW_MAX\n        ? `${flattened.slice(0, SQL_PREVIEW_MAX)}…`\n        : flattened;\n}\n\n/**\n * 从 SQL 脚本里挑出**需要确认的**语句。判据复用 `sql-risk.ts` 的 `isDestructiveSql`\n * （DROP / TRUNCATE / DELETE / ALTER…DROP|RENAME），再按调用点的**范围**收窄：\n *   - 交互式 `execute`：**DELETE 要拦**；DDL 类（DROP / TRUNCATE / ALTER…DROP）只在\n *     `allowDdlViaExecute === true` 时才可能执行，所以那时才拦（默认 false 时 DDL 走 migration，\n *     在那边拦）；\n *   - `applyMigration`：只拦 DDL 类（迁移里的 DELETE 不额外确认 —— 它是迁移的正常内容，\n *     而 Booker 给的清单就是 DROP / TRUNCATE / ALTER…DROP）。\n * `ALTER … RENAME` 在 `isDestructiveSql` 里也算破坏性，但它不改数据、也不在清单里，这里不收。\n */\nfunction pgDestructiveStatements(\n    args: Record<string, unknown>,\n    scope: { allowDelete: boolean; allowDdl: boolean },\n): string[] {\n    const sqlText = asSqlText(args.sql);\n    if (!sqlText.trim()) {\n        return [];\n    }\n    return splitSqlStatements(sqlText).filter((statement) => {\n        if (!isDestructiveSql(statement)) {\n            return false;\n        }\n        const normalized = stripLeadingSqlComments(statement);\n        const verb = getSqlVerb(normalized);\n        if (verb === \"DELETE\") {\n            return scope.allowDelete;\n        }\n        if (verb === \"ALTER\") {\n            return scope.allowDdl && /\\bDROP\\b/i.test(normalized);\n        }\n        return scope.allowDdl && (verb === \"DROP\" || verb === \"TRUNCATE\");\n    });\n}\n\nfunction pgExecuteDestructiveStatements(args: Record<string, unknown>): string[] {\n    return pgDestructiveStatements(args, {\n        allowDelete: true,\n        allowDdl: args.allowDdlViaExecute === true,\n    });\n}\n\nfunction pgApplyMigrationDestructiveStatements(args: Record<string, unknown>): string[] {\n    return pgDestructiveStatements(args, { allowDelete: false, allowDdl: true });\n}\n\n/**\n * **`rollbackSql` 有意不扫**（按裁定先判定再决定，结论：它不该被拦）。\n *\n * 判定依据（看代码，不靠印象）：`args.rollbackSql` 只在 `databasePG.ts:2443` 与 `:2593`\n * 被**存进迁移记录**（`pending.Rollback = args.rollbackSql`，类型见 `:766` `Rollback?: string`），\n * 全仓**没有任何路径执行它**——没有读 `.Rollback` 去执行的地方，也没有 migration down / rollback\n * 动作；`repairMigration` 的 `reverted` 分支（`:3218-3224`）只改 `Status`，`applied` 分支传的是\n * 修复用的 `Query`（正向前进 SQL），都不是回滚脚本。\n *\n * 所以本次调用**不会执行** rollbackSql ⇒ 因它拦下这次 forward apply 是**误报**，不收。\n * 后续项：将来若新增\"真正执行回滚\"的入口（例如 migration down / rollback 动作），\n * 那个入口必须挂同一道闸（`when` 判 `rollbackSql`，范围同 ②）。\n */\n\n/**\n * 命中的语句 → 确认框要显示的目标。\n *\n * 多条时除了 `count`，还要**换一份带 `{count}` 的文案**：预览只截首条（240 字），\n * 只点名第一条会让用户以为\"就这一条\"就点了确认。单条则沿用原文案，不出现\"共 1 条\"噪音。\n * 走的是既有机制：`DestructiveTarget.messageKey` 覆盖 spec 的 messageKey（护栏那行 `t()` 未改）。\n */\nfunction statementsTarget(\n    statements: string[],\n    manyMessageKey: MessageKey,\n): DestructiveTarget {\n    const first = statements[0];\n    return {\n        resource: first ? sqlPreview(first) : undefined,\n        ...(statements.length > 1\n            ? { count: statements.length, messageKey: manyMessageKey }\n            : {}),\n    };\n}\n\nfunction asText(value: unknown): string | undefined {\n    if (typeof value === \"string\" && value.trim().length > 0) {\n        return value.trim();\n    }\n    if (typeof value === \"number\") {\n        return String(value);\n    }\n    return undefined;\n}\n\nfunction capiParams(args: Record<string, unknown>): Record<string, unknown> {\n    const params = args.params;\n    if (params !== null && typeof params === \"object\" && !Array.isArray(params)) {\n        return params as Record<string, unknown>;\n    }\n    return {};\n}\n\n/** DeleteItem is one match unless MgoIsMulti is set. A missing flag is not a count of 1. */\nfunction capiDeleteItemTarget(args: Record<string, unknown>): DestructiveTarget {\n    const params = capiParams(args);\n    return {\n        resource: asText(params.TableName),\n        messageKey:\n            params.MgoIsMulti === true\n                ? \"confirmation.message.deleteDocumentsQuery\"\n                : \"confirmation.message.deleteDocumentsOne\",\n    };\n}\n\n/** DestroyEnv / DestroyPlatformEnv name the environment in params.EnvId, not the session binding. */\nfunction capiDestroyEnvTarget(args: Record<string, unknown>): DestructiveTarget {\n    return { resource: asText(capiParams(args).EnvId) };\n}\n\n/** DestroyMySQL takes EnvId only. The dialog must not invent an instance id. */\nfunction capiDestroyMysqlTarget(): DestructiveTarget {\n    return {\n        resource: t(\"confirmation.message.mysqlThisEnv\"),\n        messageKey: \"confirmation.message.destroyMysqlEnv\",\n    };\n}\n\nfunction capiCloudRunVersionServers(args: Record<string, unknown>): string | undefined {\n    const versions = capiParams(args).SimpleVersions;\n    if (!Array.isArray(versions)) {\n        return undefined;\n    }\n    const names: string[] = [];\n    for (const item of versions) {\n        if (item === null || typeof item !== \"object\" || Array.isArray(item)) {\n            continue;\n        }\n        const name = asText((item as Record<string, unknown>).ServerName);\n        if (name && !names.includes(name)) {\n            names.push(name);\n        }\n    }\n    return names.length > 0 ? names.join(\", \") : undefined;\n}\n\n/**\n * Document delete is keyed by `query` plus `isMulti`, not by a count.\n * `isMulti: true` removes every match; otherwise the API removes one match.\n * A `documents` array on this action is ignored by the handler, so it must not become a count.\n */\nfunction documentDeleteTarget(args: Record<string, unknown>): DestructiveTarget {\n    return {\n        resource: asText(args.collectionName),\n        messageKey:\n            args.isMulti === true\n                ? \"confirmation.message.deleteDocumentsQuery\"\n                : \"confirmation.message.deleteDocumentsOne\",\n    };\n}\n\n/** DestroyMySQL is scoped to the environment. `dbInstance` is an object, and only `instanceId` names it. */\nfunction mysqlDestroyTarget(args: Record<string, unknown>): DestructiveTarget {\n    const value = args.dbInstance;\n    const instanceId =\n        asText(value) ??\n        (value !== null && typeof value === \"object\" && !Array.isArray(value)\n            ? asText((value as Record<string, unknown>).instanceId)\n            : undefined);\n    if (instanceId) {\n        return { resource: instanceId };\n    }\n    return {\n        resource: t(\"confirmation.message.mysqlThisEnv\"),\n        messageKey: \"confirmation.message.destroyMysqlEnv\",\n    };\n}\n\n/** @todo 第一批：整资源删除（资源本身消失、影响面大且难自愈） */\nexport const DESTRUCTIVE_ACTIONS: Readonly<Record<string, DestructiveActionSpec>> = {\n    \"manageFunctions.deleteFunction\": {\n        messageKey: \"confirmation.message.deleteFunction\",\n        target: (args) => ({ resource: asText(args.functionName) }),\n    },\n    \"writeNoSqlDatabaseStructure.deleteCollection\": {\n        messageKey: \"confirmation.message.deleteCollection\",\n        target: (args) => ({ resource: asText(args.collectionName) }),\n    },\n    \"writeNoSqlDatabaseContent.delete\": {\n        messageKey: \"confirmation.message.deleteDocumentsOne\",\n        target: documentDeleteTarget,\n    },\n    \"manageStorage.delete\": {\n        messageKey: \"confirmation.message.deleteStorage\",\n        target: (args) => ({ resource: asText(args.cloudPath) }),\n    },\n    \"manageCloudRun.delete\": {\n        messageKey: \"confirmation.message.deleteCloudRun\",\n        target: (args) => ({ resource: asText(args.serverName) }),\n    },\n    \"manageMysqlDatabase.destroyMySQL\": {\n        messageKey: \"confirmation.message.destroyMysql\",\n        target: mysqlDestroyTarget,\n    },\n\n    // 谓词型（参数里确实有破坏性 SQL 才拦）：\n    \"managePgDatabase.execute\": {\n        messageKey: \"confirmation.message.pgExecuteDestructiveSql\",\n        when: (args) => pgExecuteDestructiveStatements(args).length > 0,\n        target: (args) =>\n            statementsTarget(\n                pgExecuteDestructiveStatements(args),\n                \"confirmation.message.pgExecuteDestructiveSqlMany\",\n            ),\n    },\